sys_script_include.script:
var separationUtils = Class.create();
separationUtils.prototype = {
    initialize: function() {
    },

	hasEntityWrite: function() {
		var grantAccess = false;
// gs.addInfoMessage(current.owned_by);

		var grOwnergroup = new GlideRecord('sys_user_grmember');
		grOwnergroup.addEncodedQuery('groupLIKEFin Ops^user=' + current.owned_by);
		grOwnergroup.query();
		if(grOwnergroup.hasNext()) {
			grOwnergroup.next();
			var region = grOwnergroup.group.getDisplayValue().substring(0,2);
			// gs.addInfoMessage(region);
			var currentUserGroup = new GlideAggregate('sys_user_grmember');
			currentUserGroup.addAggregate('COUNT');
			currentUserGroup.addQuery('group', grOwnergroup.group);
			currentUserGroup.addQuery('user',gs.getUserID());
			// currentUserGroup.addQuery('user','be82abf03710200044e0bfc8bcbe5d1c');
			currentUserGroup.query();
			currentUserGroup.next();
			if(currentUserGroup.getAggregate('COUNT') > 0) return true;

		}
		//gs.info('Has Access: ' + grantAccess);
// gs.addInfoMessage('Has Access: ' + grantAccess);
		return false;
	},

    type: 'separationUtils'
};
